import sys
import csv
from datetime import datetime

def validate_record(record):
    errors = []
    try:
        employee_id = int(record['employee_id'])
        if employee_id <= 0:
            errors.append(('employee_id', 'must be a positive integer'))
    except ValueError:
        errors.append(('employee_id', 'must be a positive integer'))

    if not record['first_name'].strip():
        errors.append(('first_name', 'must be non-empty'))

    if not record['last_name'].strip():
        errors.append(('last_name', 'must be non-empty'))

    email = record['email'].strip()
    if email.count('@') != 1 or not email.endswith('.com'):
        errors.append(('email', 'must contain exactly one "@" and end with ".com"'))

    try:
        salary = float(record['salary'])
        if salary <= 0:
            errors.append(('salary', 'must be a positive number'))
    except ValueError:
        errors.append(('salary', 'must be a positive number'))

    return errors if errors else None

def main():
    if len(sys.argv) != 2:
        print("Usage: python process.py <input_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    try:
        with open(input_file, 'r') as f:
            reader = csv.DictReader(f)
            valid_rows = []
            log_file = open('validation.log', 'a', newline='')
            line_number = 1

            for row in reader:
                line_number += 1
                errors = validate_record(row)
                if errors:
                    timestamp = datetime.now().isoformat()
                    log_file.write(f"{timestamp} {line_number} Invalid {errors[0][0]}: {errors[0][1]}\n")
                else:
                    valid_rows.append(row)

            log_file.close()

            if not valid_rows:
                print("No valid records found.", file=sys.stderr)
                sys.exit(1)

            with open('valid_records.csv', 'w', newline='') as f:
                writer = csv.DictWriter(f, fieldnames=reader.fieldnames)
                writer.writeheader()
                writer.writerows(valid_rows)

    except IOError:
        with open('validation.log', 'a') as log_file:
            log_file.write(f"{datetime.now().isoformat()} Failed to open input file\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import csv
import logging
from datetime import datetime

def validate_record(line_number, fields):
    errors = []
    if not fields['employee_id'].isdigit():
        errors.append(('employee_id', 'must be a positive integer'))
    else:
        emp_id = int(fields['employee_id'])
        if emp_id <= 0:
            errors.append(('employee_id', 'must be a positive integer'))

    if not fields['salary'].lstrip('-').replace('.', '', 1).isdigit():
        errors.append(('salary', 'must be a positive number'))
    else:
        try:
            salary = float(fields['salary'])
            if salary <= 0:
                errors.append(('salary', 'must be a positive number'))
        except ValueError:
            errors.append(('salary', 'must be a positive number'))

    return errors if errors else None

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <input_csv_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    try:
        with open(input_file, 'r') as f:
            reader = csv.DictReader(f)
            if not reader.fieldnames == ['employee_id', 'name', 'salary']:
                print("Error: CSV header does not match expected columns.", file=sys.stderr)
                sys.exit(1)

            valid_records = []
            validation_log = []
            line_number = 1

            for row in reader:
                errors = validate_record(line_number, row)
                if errors:
                    timestamp = datetime.now().isoformat()
                    validation_log.append(f"{timestamp} {line_number} Invalid {errors[0][0]}: {errors[0][1]}")
                else:
                    valid_records.append(row)
                line_number += 1

            if not validation_log:
                validation_log.append(f"{datetime.now().isoformat()} Failed to open input file")

            with open('validation.log', 'w') as log_file:
                log_file.write('\n'.join(validation_log))

            with open('valid_records.csv', 'w', newline='') as out_file:
                writer = csv.DictWriter(out_file, fieldnames=reader.fieldnames)
                writer.writeheader()
                writer.writerows(valid_records)

            sys.exit(0)

    except IOError:
        timestamp = datetime.now().isoformat()
        with open('validation.log', 'w') as log_file:
            log_file.write(f"{timestamp} Failed to open input file")
        sys.exit(1)

if __name__ == "__main__":
    main()
